using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Threading.Tasks;using System.Collections.Generic;
namespace V15Voice {public partial class MainForm {
 readonly LatestRenderUpdate fastUi=new LatestRenderUpdate();DateTime fastClock=DateTime.MinValue;bool refreshingJobs;volatile bool batchUtilityCancelled;
 readonly List<Tuple<bool,Label,BeoButton[],ToolTip>> voiceAdviceViews=new List<Tuple<bool,Label,BeoButton[],ToolTip>>();readonly Dictionary<bool,string> voiceAdviceKeys=new Dictionary<bool,string>();
 long fullQueueRebuilds;readonly Dictionary<BatchJob,string> fastRowKeys=new Dictionary<BatchJob,string>();
 void PublishRenderUi(int value,string text){fastUi.Publish(value,text);}
 void FlushRenderUi(){int value;string message,device;if(!fastUi.Take(out value,out message,out device))return;if(message.Length>0)status.Text=message;if(device.Length>0)deviceStatus.Text=device;RefreshBeoProgress();if(busy&&beoActiveJobs!=null)SaveQueueIfChanged();}
 void FastUiTick(){FlushRenderUi();if((DateTime.UtcNow-fastClock).TotalSeconds>=1){fastClock=DateTime.UtcNow;RefreshBeoProgress();}}
 void SetFastVoiceBusy(bool value){foreach(var view in voiceAdviceViews)foreach(var b in view.Item3){var item=b.Tag as VoiceSuggestion;b.Enabled=!value&&item!=null&&item.Available;}}
 void SelectBatchFiles(int choice){if(busy)return;foreach(var job in jobs)job.Selected=choice==0||(choice==1&&job.State!=JobState.Done);RefreshBeoRows();SaveSession();}
 async Task AddBatchFolder(){if(busy)return;using(var d=new FolderBrowserDialog{Description="Chọn thư mục SRT · gồm thư mục con · bỏ final.srt/aligned.srt"})if(d.ShowDialog()==DialogResult.OK)await ImportBatchInputs(new[]{d.SelectedPath});}
 async Task ImportBatchInputs(IEnumerable<string> paths){if(busy)return;string[] inputs=paths.ToArray(),existing=jobs.Select(j=>j.InputPath).ToArray();int capacity=500-jobs.Count;batchUtilityCancelled=false;fastUi.Clear();SetBusy(true);try{var result=await Task.Run(()=>BatchImport.Read(inputs,existing,capacity,()=>batchUtilityCancelled,m=>fastUi.Publish(0,m)));foreach(var job in result.Jobs){jobs.Add(job);DetectSpeakers(job.Cues);}tabs.SelectedTab=batchPage;RefreshJobs();status.Text=result.Summary;if(result.Warnings.Count>0)batchInfo.Text=String.Join(" · ",result.Warnings.Take(2));}
  catch(OperationCanceledException){status.Text="Đã dừng nhập · hàng đợi hiện tại được giữ.";}catch(Exception ex){status.Text="Chưa nhập được thư mục: "+ex.Message;}finally{fastUi.Clear();SetBusy(false);SaveSession();}}
 string BatchRunKey(VoiceSettings settings){var xml=settings.Xml();xml.Attribute("name").Remove();xml.Attribute("skip").Remove();var keys=new[]{settings.Key,settings.TwoVoices?settings.VoiceBKey:""};string assets="";foreach(string key in keys.Where(k=>!String.IsNullOrEmpty(k))){var p=catalog.Get(key);using(var e=AdviceEngine(p))assets+="|"+SpeechArchive.Key(e,"batch-output-profile",settings.Speed);}if(settings.Breathing==(int)BreathMode.Custom&&!String.IsNullOrEmpty(settings.BreathPath)&&File.Exists(settings.BreathPath))assets+="|"+StateFiles.Hash(settings.BreathPath);if(settings.Breathing==(int)BreathMode.Auto&&Directory.Exists(Path.Combine(root,"breaths")))foreach(string path in Directory.GetFiles(Path.Combine(root,"breaths"),"*.wav").OrderBy(p=>p,StringComparer.Ordinal))assets+="|"+Path.GetFileName(path)+"|"+StateFiles.Hash(path);return SpeechArchive.Hash("batch410|"+xml.ToString(System.Xml.Linq.SaveOptions.DisableFormatting)+assets);}
 KokoroEngine AdviceEngine(VoiceProfile p){return new KokoroEngine{Root=root,Kind=p.Kind,Speaker=p.Speaker,ModelFolder=p.ModelFolder,VoiceName=p.Name,ReferencePath=p.ReferencePath,ReferenceText=p.ReferenceText,DeviceMode=SelectedDevice()};}
 Control BuildVoiceAdvice(bool batch){var host=new TableLayoutPanel{Name=batch?"batchVoiceAdvice":"studioVoiceAdvice",ColumnCount=1,RowCount=2,Height=batch?150:66,Width=254,Margin=new Padding(0,0,0,10),Dock=batch?DockStyle.None:DockStyle.Fill};host.RowStyles.Add(new RowStyle(SizeType.Absolute,batch?38:22));host.RowStyles.Add(new RowStyle(SizeType.Percent,100));var label=new Label{Text="Gợi ý giọng khi nhập SRT/TXT · chưa đo",Dock=DockStyle.Fill,AutoEllipsis=true,Tag="muted",Font=new Font("Segoe UI",8.5f)};host.Controls.Add(label,0,0);var picks=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=batch?1:3,RowCount=batch?3:1,Margin=Padding.Empty};if(batch){for(int i=0;i<3;i++)picks.RowStyles.Add(new RowStyle(SizeType.Percent,33.333f));}else for(int i=0;i<3;i++)picks.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,33.333f));host.Controls.Add(picks,0,1);var buttons=new BeoButton[3];var tips=new ToolTip();for(int i=0;i<3;i++){var b=new BeoButton{Text="—",Dock=DockStyle.Fill,MinimumSize=new Size(50,30),Margin=new Padding(0,0,5,4),Enabled=false,Font=new Font("Segoe UI",9)};buttons[i]=b;picks.Controls.Add(b,batch?0:i,batch?i:0);b.Click+=(s,e)=>{var suggestion=b.Tag as VoiceSuggestion;if(busy||suggestion==null||!suggestion.Available)return;SelectVoice(suggestion.Profile.Key);status.Text="Đã chọn giọng "+suggestion.Profile.Name+" · bấm Nghe thử để xác nhận; gợi ý chưa đo timeline.";};}voiceAdviceViews.Add(Tuple.Create(batch,label,buttons,tips));host.Disposed+=(s,e)=>tips.Dispose();return host;}
 void AddStudioVoiceAdvice(){var left=wavePanel.Parent as TableLayoutPanel;if(left==null)return;left.Controls.Remove(wavePanel);left.RowStyles[3].Height=132;var host=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2,Margin=Padding.Empty};host.RowStyles.Add(new RowStyle(SizeType.Absolute,66));host.RowStyles.Add(new RowStyle(SizeType.Percent,100));host.Controls.Add(BuildVoiceAdvice(false),0,0);host.Controls.Add(wavePanel,0,1);left.Controls.Add(host,0,3);}
 void RefreshVoiceAdvice(bool batch,bool force=false){if(busy||refreshingJobs||catalog==null||voiceAdviceViews.Count==0)return;var source=batch?(jobGrid.CurrentRow==null?null:jobs.ElementAtOrDefault(jobGrid.CurrentRow.Index)):null;var script=batch?(source==null?new List<Cue>():source.Cues):cues;string preferred=voices.SelectedItem==null?"":Key();string key=AiRepairSession.SnapshotHash(script.Take(40).ToList())+"|"+preferred+"|"+catalog.Count;string previous;if(!force&&voiceAdviceKeys.TryGetValue(batch,out previous)&&previous==key)return;voiceAdviceKeys[batch]=key;var advice=VoiceRecommendations.Analyze(script,catalog.All,preferred,p=>{using(var e=AdviceEngine(p)){e.CheckFiles();return true;}});foreach(var view in voiceAdviceViews.Where(v=>v.Item1==batch)){view.Item2.Text=advice.Note;for(int i=0;i<view.Item3.Length;i++){var b=view.Item3[i];var item=advice.Suggestions.ElementAtOrDefault(i);b.Tag=item;b.Enabled=item!=null&&item.Available;b.Text=item==null?"—":(i+1)+". "+item.Profile.Name+(item.Available?"":" · cần cài");b.Selected=item!=null&&item.Profile.Key==preferred;view.Item4.SetToolTip(b,item==null?advice.Note:item.Profile.Kind+" · "+item.Profile.Gender+"\r\n"+item.Reason+"\r\nChưa tổng hợp hoặc đo giọng. Bấm để chọn.");b.Invalidate();}}}
 void BuildBatchUtilities(FlowLayoutPanel tools,FlowLayoutPanel side){var folder=Btn("+ Thư mục SRT",async(s,e)=>await AddBatchFolder());folder.Name="batchFolderImport";tools.Controls.Add(folder);var select=Btn("Chọn ▾",(s,e)=>{});select.Name="batchSelectFiles";var menu=new ContextMenuStrip();menu.Items.Add("Chọn tất cả",null,(s,e)=>SelectBatchFiles(0));menu.Items.Add("Chọn file chưa đạt",null,(s,e)=>SelectBatchFiles(1));menu.Items.Add("Bỏ chọn tất cả",null,(s,e)=>SelectBatchFiles(2));select.Click+=(s,e)=>{beoTheme.Apply(menu,beoAppearance.Theme,beoAppearance.Scale);menu.Show(select,0,select.Height);};tools.Controls.Add(select);side.Controls.Add(BuildVoiceAdvice(true));side.Controls.SetChildIndex(side.Controls[side.Controls.Count-1],1);BeoMirror(side,"Bộ cấu hình đã lưu",presetPicker);var actions=new FlowLayoutPanel{Width=254,Height=42,WrapContents=false,Margin=Padding.Empty};actions.Controls.Add(Btn("Áp dụng",(s,e)=>{var p=presetPicker.SelectedItem as VoiceSettings;if(p!=null){Apply(p);SaveSession();status.Text="Đã áp dụng cấu hình "+p.Name+" cho lượt chạy hàng đợi.";RefreshVoiceAdvice(true,true);}}));actions.Controls.Add(Btn("Lưu",(s,e)=>SavePreset()));side.Controls.Add(actions);foreach(Control c in actions.Controls)extraControls.Add(c);}
 void UpdateBatchRow(DataGridViewRow row,BatchJob job){var p=job.Progress.Read();string eta=job.State==JobState.Running?p.Eta:job.State==JobState.Done?"Đã xong":job.State==JobState.Queued?"Chờ tới lượt":"—";string detail=job.State==JobState.Running?p.Phase:job.Error.Length>0?job.Error:job.State==JobState.Done?"WAV + SRT đã kiểm tra":job.State==JobState.TranslationIncomplete?"WAV đạt · bản dịch chưa đủ":job.State==JobState.NeedsReview?"Xem báo cáo; checkpoint đã giữ":job.Warning;
  string key=job.Selected+"|"+job.State+"|"+p.Percent+"|"+eta+"|"+detail+"|"+CurrentBeoPalette.Surface.ToArgb()+"|"+CurrentBeoPalette.Accent.ToArgb();string old;if(fastRowKeys.TryGetValue(job,out old)&&old==key)return;fastRowKeys[job]=key;SetBatchCell(row,"completion",p.Percent);SetBatchCell(row,"eta",eta);SetBatchCell(row,"selected",job.Selected);SetBatchCell(row,"Trạng thái",job.Status);SetBatchCell(row,"Kết quả / lỗi",detail);row.DefaultCellStyle.BackColor=job.State==JobState.Failed||job.State==JobState.ImportFailed?CurrentBeoPalette.Error:job.State==JobState.NeedsReview||job.State==JobState.TranslationIncomplete?CurrentBeoPalette.Warning:CurrentBeoPalette.Surface;row.DefaultCellStyle.ForeColor=CurrentBeoPalette.Text;
 }
 static void SetBatchCell(DataGridViewRow row,string name,object value){if(!Object.Equals(row.Cells[name].Value,value))row.Cells[name].Value=value;}
}
